using GestorExcursiones.Domain.Entities;using GestorExcursiones.Infrastructure.Repositories;using GestorExcursiones.API.Models.Dtos;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace GestorExcursiones.API.Controllers;
[ApiController][Route("api/[controller]")] public class ClientsController(ClienteRepository repo):ControllerBase{
 [HttpGet] public async Task<ActionResult<IEnumerable<ClientDto>>> GetAll()=>Ok((await repo.GetAllAsync()).Select(Map));
 [HttpGet("{id:int}")] public async Task<ActionResult<ClientDto>> GetById(int id){var x=await repo.GetByIdAsync(id);return x is null?NotFound():Ok(Map(x));}
 [HttpPost] public async Task<ActionResult<ClientDto>> Create(ClientCreateDto d){if(await repo.DocumentoExisteAsync(d.DocumentoIdentificacion))return Conflict("Ya existe un cliente con ese documento.");var x=new Cliente{Nombre=d.Nombre,Apellido=d.Apellido,DocumentoIdentificacion=d.DocumentoIdentificacion,Telefono=d.Telefono,CorreoElectronico=d.CorreoElectronico};await repo.AddAsync(x);return CreatedAtAction(nameof(GetById),new{id=x.Id},Map(x));}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,ClientCreateDto d){var x=await repo.GetByIdAsync(id);if(x is null)return NotFound();if(x.DocumentoIdentificacion!=d.DocumentoIdentificacion&&await repo.DocumentoExisteAsync(d.DocumentoIdentificacion))return Conflict("Documento duplicado.");x.Nombre=d.Nombre;x.Apellido=d.Apellido;x.DocumentoIdentificacion=d.DocumentoIdentificacion;x.Telefono=d.Telefono;x.CorreoElectronico=d.CorreoElectronico;await repo.UpdateAsync(x);return NoContent();}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){try{return await repo.DeleteAsync(id)?NoContent():NotFound();}catch(DbUpdateException){return Conflict("El cliente tiene reservas asociadas.");}}
 static ClientDto Map(Cliente x)=>new(){Id=x.Id,Nombre=x.Nombre,Apellido=x.Apellido,DocumentoIdentificacion=x.DocumentoIdentificacion,Telefono=x.Telefono,CorreoElectronico=x.CorreoElectronico};}
